def armar_usuarios(apps, schema_editor):
    """A los que no tienen mail (entran con PIN) les arma el usuario con el nombre, como Usuario.save()."""
    Usuario = apps.get_model('usuarios', 'Usuario')
    tomados = set(Usuario.objects.exclude(usuario=None).values_list('usuario', flat=True))
    for u in Usuario.objects.filter(email=None, usuario=None).order_by('pk'):
        base = slugify(u.nombre or '')[:36].strip('-_.') or 'usuario'
        if len(base) < 2:
            base = f'{base}0'
        candidato, n = base, 2
        while candidato in tomados:
            candidato, n = f'{base}{n}', n + 1
        tomados.add(candidato)
        Usuario.objects.filter(pk=u.pk).update(usuario=candidato)


